initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a list of Context Source Registrations (CSRs) providing latest information about some entities
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Query Context Source Registrations with Response Status Code set to 200     and
        Query Context Source Registrations with Response Body containing a list of entities equal to '${1}' of type 'ContextSourceRegistration' with response set to '${response.json()}'     and
        Query Context Source Registrations with Response header with 'Prev' header equal to '</ngsi-ld/v1/csourceSubscriptions?type=Building&limit=1&page=3>;rel="next";type="application/ld+json"' and with 'Next' header equal to '${response.json()}'
}

then {
    the SUT sends a valid Response for the operations:
        Query Context Source Registrations with Response Status Code set to 200     and
        Query Context Source Registrations with Response Body containing a list of entities equal to '${1}' of type 'ContextSourceRegistration' with response set to '${response.json()}'     and
        Query Context Source Registrations with Response header with 'Prev' header equal to '${EMPTY}' and with 'Next' header equal to '${response.json()}'
}

then {
    the SUT sends a valid Response for the operations:
        Query Context Source Registrations with Response Status Code set to 200     and
        Query Context Source Registrations with Response Body containing a list of entities equal to '${3}' of type 'ContextSourceRegistration' with response set to '${response.json()}'     and
        Query Context Source Registrations with Response header with 'Prev' header equal to '${EMPTY}' and with 'Next' header equal to '${response.json()}'
}
